def compute_mobius(n):
    if n == 0:
        return 0
    if n == 1:
        return 1
    factors = set()
    temp = n
    i = 2
    while i * i <= temp:
        if temp % i == 0:
            count = 0
            while temp % i == 0:
                temp //= i
                count += 1
            if count > 1:
                return 0
            factors.add(i)
        i += 1
    if temp > 1:
        factors.add(temp)
    return (-1) ** len(factors)

